import{_ as i,l as o,o as a,c as n,v as r,p as s,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"秘书问题","description":"","frontmatter":{"title":"秘书问题","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/secretary-problem.md","filePath":"cs/secretary-problem.md","lastUpdated":1789023840000}'),h={name:"cs/secretary-problem.md"};function _(m,e,u,E,b,f){const l=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="秘书问题" tabindex="-1">秘书问题 <a class="header-anchor" href="#秘书问题" aria-label="Permalink to &quot;秘书问题&quot;">​</a></h1><div class="epigraph"><p>$n$ 个候选人依次出现、比较只见相对序；看过约 $n/e$ 个后录用下一个纪录，成功概率趋于 $1/e$。</p><footer>—— 据 Dynkin；Gilbert and Mosteller, Recognizing the Maximum of a Sequence, 1966；标准最优停止整理</footer></div><p>上一课<a href="/cs/ski-rental">租买</a>是买断阈值。秘书：选最大，不可悔。缺口是 \\(1/e\\) 规则。不重写竞争比的 \\(\\rho\\) 定义——本课是成功概率（随机排列）。后课老虎机另一不确定。排列均匀随机，不是对手任意权。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>见过 \\(i\\) 后只知是否当前最大。拒绝不能再召回。最优：阈值 \\(r\\sim n/e\\)，拒绝前 \\(r\\)，之后第一个超过前 \\(r\\) 最大值的就选。\\(P(\\text{选中全局最大})\\to 1/e\\)。</p><p>缺口是最优停止，不是排序。若值为 i.i.d. 连续，等价于秩。</p><h3 id="不是招聘的人力资源课" tabindex="-1">不是招聘的人力资源课 <a class="header-anchor" href="#不是招聘的人力资源课" aria-label="Permalink to &quot;不是招聘的人力资源课&quot;">​</a></h3><p>模型是随机排列。对手指定顺序可让任何算法失败。不要当确定性竞争比 \\(O(1)\\)——确定性看完才能保证最大。</p><p><span class="marginnote">Gilbert–Mosteller 1966。\\(1/e\\) 古典。后课 UCB 是多臂，可重复拉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>证明 \\(r\\) 最优：成功 = 最大在 \\(j\\gt r\\) 且 \\(j\\) 前缀最大在前 \\(r\\)。求和 \\(\\approx \\int_{r/n}^1 -\\ln x\\,dx\\) 在 \\(r/n=1/e\\) 最大。</p>',11)),(a(),s(c,null,{default:t(()=>[p(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEE%5B%22%E8%A7%82%E5%AF%9F%E5%89%8D%20n%2Fe%22%5D%20--%3E%20THR%5B%22%E9%98%88%E5%80%BC%E7%BA%AA%E5%BD%95%22%5D%0A%20%20THR%20--%3E%20HIRE%5B%22%E5%85%B6%E5%90%8E%E7%AC%AC%E4%B8%80%E4%B8%AA%E7%BA%AA%E5%BD%95%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>\\(n\\) 未知时另有策略，点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息与机会的折中：观察太少阈值差，太多已过最大。与 ski-rental：都是阈值；一个代价竞争，一个成功概率。与顺序统计。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多选、不写折扣。后课默认：秘书 \\(n/e\\) 规则，\\(1/e\\)。下一课多臂老虎机 UCB。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机排列下 \\(n/e\\) 后录用纪录。</li><li>成功概率 \\(1/e\\)。</li><li>对抗顺序无常数保证。</li><li>出处：Gilbert and Mosteller, 1966。</li></ul>',7))])}const T=i(h,[["render",_]]);export{x as __pageData,T as default};
